      hu: "A Piz Bernina 4049 méteres magasságával a Keleti-Alpok legmagasabb csúcsa. Graubünden kantonban található, a Bernina-hegycsoport legmagasabb pontja.",
      ro: "Piz Bernina este cel mai înalt vârf din Alpii Orientali, având 4049 de metri. Este situat în cantonul Graubünden și marchează punctul culminant al masivului Bernina.",
