    imageHint: "Piz d'Err mountain peak",
    descriptionAdvanced: {
      de: "Der Piz d'Err ist ein markanter Berg in den Albula-Alpen im Kanton Graubünden und erreicht eine Höhe von 3378 Metern. Er ist der höchste Gipfel der Err-Gruppe, die sich zwischen dem Oberhalbstein und dem Albulatal erstreckt. Geologisch ist der Berg durch kristallines Gestein geprägt, was ihm eine zerklüftete und imposante Struktur verleiht. Die Erstbesteigung gelang im Jahr 1864 durch den berühmten Geodäten Johann Coaz zusammen mit seinen Begleitern. Der Piz d'Err ist im Vergleich zu seinen Nachbarn wie dem Piz Kesch weniger überlaufen, bietet aber eine ebenso spektakuläre Aussicht auf das Engadin und die Bernina-Gruppe. Der Aufstieg erfolgt meist von der Chamanna d'Err oder der Es-cha-Hütte und erfordert alpinistische Erfahrung sowie Trittsicherheit in felsigem Gelände. In der Umgebung befinden sich mehrere kleine Gletscher, die jedoch aufgrund des Klimawandels stark zurückgegangen sind. Der Berg bleibt ein Geheimtipp für Bergsteiger, die Einsamkeit und technische Herausforderungen in der alpinen Wildnis Graubündens suchen.",
      hu: "A Piz d'Err az Albula-Alpok egyik meghatározó hegye Graubünden kantonban, amely 3378 méteres magasságot ér el. Ez az Err-csoport legmagasabb csúcsa, amely az Oberhalbstein és az Albula-völgy között húzódik. Geológiailag kristályos kőzetek jellemzik, ami csipkézett és impozáns szerkezetet kölcsönöz neki. Az első megmászása 1864-ben történt a híres geodéta, Johann Coaz és társai által. A Piz d'Err kevésbé zsúfolt, mint szomszédai, például a Piz Kesch, de hasonlóan látványos kilátást nyújt az Engadinra és a Bernina-csoportra. A feljutás általában a Chamanna d'Err vagy az Es-cha menedékháztól indul, és alpesi tapasztalatot, valamint biztos mozgást igényel a sziklás terepen. A környezetében több kisebb gleccser található, amelyek a klímaváltozás hatására jelentősen visszahúzódtak. A hegy továbbra is titkos tippnek számít azon hegymászók számára, akik a magányt és a technikai kihívásokat keresik Graubünden alpesi vadonjában.",
      ro: "Piz d'Err este un munte remarcabil din Alpii Albula, situat în cantonul Graubünden, atingând o înălțime de 3378 de metri. Este cel mai înalt vârf din grupul Err, care se întinde între Oberhalbstein și Valea Albula. Din punct de vedere geologic, muntele este caracterizat de roci cristaline, ceea ce îi conferă o structură accidentată și impunătoare. Prima ascensiune a fost realizată în anul 1864 de către faimosul geodez Johann Coaz, împreună cu însoțitorii săi. Piz d'Err este mai puțin aglomerat comparativ cu vecinii săi, precum Piz Kesch, dar oferă o vedere la fel de spectaculoasă asupra Engadinei și grupului Bernina. Ascensiunea se face de obicei de la Chamanna d'Err sau cabana Es-cha și necesită experiență alpină și siguranță în teren stâncos. În împrejurimi se află mai mulți ghețari mici, care însă s-au retras semnificativ din cauza schimbărilor climatice. Muntele rămâne o recomandare pentru alpiniștii care caută singurătatea și provocările tehnice în sălbăticia alpină din Graubünden.",
      en: "Piz d'Err is a prominent mountain in the Albula Alps of the canton of Graubünden, reaching an elevation of 3,378 meters. It is the highest peak in the Err group, which lies between the Oberhalbstein and the Albula Valley. Geologically, the mountain is defined by crystalline rock, giving it a rugged and imposing structure. The first recorded ascent was achieved in 1864 by the famous surveyor Johann Coaz and his companions. Compared to its neighbors like Piz Kesch, Piz d'Err is less crowded but offers equally spectacular views of the Engadine and the Bernina Range. The ascent typically starts from the Chamanna d'Err or the Es-cha Hut and requires mountaineering experience and sure-footedness in rocky terrain. Several small glaciers are located in its vicinity, though they have significantly retreated due to climate change. The mountain remains a hidden gem for climbers seeking solitude and technical challenges in the alpine wilderness of Graubünden.",
      es: "El Piz d'Err es una montaña en el cantón de los Grisones, en el área de Albula. Se encuentra al sur del paso de Julier. Su altura es de 3374 m. La montaña fue escalada por primera vez en 1864 por un grupo de topógrafos suizos. El Piz d'Err consiste en dolomita y piedra caliza. La región es conocida por sus formaciones geológicas. El turismo juega un papel importante, con rutas de senderismo y la proximidad al paso de Julier. La montaña es un destino popular para escaladores. Las vistas incluyen la Engadina y los Alpes de Bernina.",
      pt: "O Piz d'Err é uma montanha no cantão dos Grisões, na área de Albula. Situa-se a sul do passo de Julier. A altura é de 3374 m. A montanha foi escalada pela primeira vez em 1864 por um grupo de topógrafos suíços. O Piz d'Err é constituído por dolomite e calcário. A região é conhecida pelas suas formações geológicas. O turismo desempenha um papel importante, com trilhos para caminhadas e a proximidade do passo de Julier. A montanha é um destino popular para escaladores. A vista inclui a Engadina e os Alpes de Bernina.",
      fr: "Le Piz d'Err est une montagne dans le canton des Grisons, dans la zone de l'Albula. Il se trouve au sud du col du Julier. Son altitude est de 3374 m. La montagne a été gravie pour la première fois en 1864 par un groupe de géomètres suisses. Le Piz d'Err est composé de dolomite et de calcaire. La région est connue pour ses formations géologiques. Le tourisme joue un rôle, avec des sentiers de randonnée et la proximité du col du Julier. La montagne est une destination prisée des grimpeurs. La vue englobe l'Engadine et les Alpes de la Bernina.",
    },
    factsAdvanced: {
      de: ["Die offizielle Höhe des Piz d'Err beträgt 3378 Meter.", "Johann Coaz führte die Erstbesteigung im Jahr 1864 durch.", "Der Berg ist der Namensgeber der Err-Gruppe in den Albula-Alpen.", "Geografisch liegt er zwischen den Gemeinden Savognin und Bever.", "Die Nordostflanke beherbergt Reste des Err-Gletschers.", "Der Gipfel bietet eine weite Sicht bis zum Ortler und zum Piz Bernina."],
      hu: ["A Piz d'Err hivatalos magassága 3378 méter.", "Johann Coaz vezette az első sikeres megmászást 1864-ben.", "A hegy az Albula-Alpokhoz tartozó Err-csoport névadója.", "Földrajzilag Savognin és Bever települések között helyezkedik el.", "Az északkeleti oldalon találhatók az Err-gleccser maradványai.", "A csúcsról tiszta időben az Ortler is jól látható."],
      ro: ["Înălțimea oficială a vârfului Piz d'Err este de 3378 de metri.", "Johann Coaz a condus prima ascensiune reușită în anul 1864.", "Muntele dă numele grupului Err din Alpii Albula.", "Geografic, este situat între localitățile Savognin și Bever.", "Pe versantul nord-estic se află resturile ghețarului Err.", "Vârful oferă o panoramă vastă până la masivul Ortler și Piz Bernina."],
      en: ["The official elevation of Piz d'Err is 3,378 meters.", "Johann Coaz completed the first recorded ascent in 1864.", "The mountain is the namesake of the Err Group in the Albula Alps.", "It is located between the municipalities of Savognin and Bever.", "The northeastern flank contains remnants of the Err Glacier.", "It is considered one of the most significant peaks in central Graubünden."],
      es: ["Altitud: 3374 m", "Primera ascensión: 1864", "Geología: Dolomita y piedra caliza", "Cantón: Grisones", "Localidad más cercana: Silvaplana (10 km)", "Número de rutas de escalada: 15"],
      pt: ["Altitude: 3374 m", "Primeira ascensão: 1864", "Geologia: Dolomite e calcário", "Cantão: Grisões", "Localidade mais próxima: Silvaplana (10 km)", "Número de rotas de escalada: 15"],
      fr: ["Altitude : 3374 m", "Première ascension : 1864", "Géologie : Dolomite et calcaire", "Canton : Grisons", "Localité la plus proche : Silvaplana (10 km)", "Nombre de voies d'escalade : 15"],
    },
