    imageHint: "Piz Val Gronda landscape",
    descriptionAdvanced: {
      de: "Der Piz Val Gronda ist ein Berggipfel in den Samnaungruppe und erreicht eine Höhe von 2812 Metern. Er liegt direkt auf der Grenze zwischen der Schweiz (Kanton Graubünden) und Österreich (Tirol). Der Berg ist Teil der Silvretta-Arena, eines der größten zusammenhängenden Skigebiete der Alpen, das die Orte Ischgl und Samnaun verbindet. Eine moderne Pendelbahn führt seit 2013 bis knapp unter den Gipfel und hat den Berg für den Massentourismus erschlossen. Trotz der technischen Erschließung bewahrt die Nordseite des Berges einen wilden Charakter und ist ein beliebtes Ziel für Freerider und Tourengänger. Geologisch besteht das Gebiet aus kristallinen Gesteinen der Silvretta-Decke. Die Flora in den Sommermonaten ist bemerkenswert reichhaltig, da der Berg in einer klimatischen Übergangszone liegt. Der Gipfel bietet einen weiten Blick über das Paznauntal und die vergletscherten Gipfel der Silvretta-Gruppe.",
      hu: "A Piz Val Gronda a Samnaun-csoport egyik hegycsúcsa, amely 2812 méteres magasságot ér el. Közvetlenül Svájc (Graubünden kanton) és Ausztria (Tirol) határán fekszik. A hegy a Silvretta-Arena része, amely az Alpok egyik legnagyobb összefüggő síterepe, összekötve Ischgl és Samnaun településeit. 2013 óta egy modern inga felvonó vezet majdnem a csúcsig, megnyitva a hegyet a tömegturizmus előtt. A technikai kiépítés ellenére a hegy északi oldala megőrizte vad karakterét, és a freeride síelők, valamint a sítúrázók kedvelt célpontja. Geológiailag a terület a Silvretta-takaró kristályos kőzeteiből áll. A nyári hónapok növényvilága kiemelkedően gazdag, mivel a hegy egy éghajlati átmeneti zónában található. A csúcsról tágas kilátás nyílik a Paznaun-völgyre és a Silvretta-csoport eljegesedett csúcsaira.",
      ro: "Piz Val Gronda este un vârf montan din grupul Samnaun, atingând o înălțime de 2812 metri. Acesta este situat direct pe granița dintre Elveția (cantonul Graubünden) și Austria (Tirol). Muntele face parte din Silvretta Arena, una dintre cele mai mari zone de schi conexe din Alpi, care leagă localitățile Ischgl și Samnaun. Din anul 2013, o telecabină modernă pendulară duce până aproape de vârf, făcând muntele accesibil turismului de masă. În ciuda dezvoltării tehnice, versantul nordic al muntelui își păstrează caracterul sălbatic și este o destinație populară pentru schiorii de freeride și turiștii pe schiuri. Din punct de vedere geologic, zona este formată din roci cristaline ale pânzei Silvretta. Flora din lunile de vară este remarcabil de bogată, deoarece muntele se află într-o zonă de tranziție climatică. Vârful oferă o vedere largă asupra văii Paznaun și a vârfurilor înghețate ale grupului Silvretta.",
      en: "Piz Val Gronda is a mountain peak in the Samnaun Alps, reaching an elevation of 2,812 meters. It is situated directly on the border between Switzerland (canton of Graubünden) and Austria (Tyrol). The mountain is part of the Silvretta Arena, one of the largest interconnected ski resorts in the Alps, linking the towns of Ischgl and Samnaun. Since 2013, a modern aerial tramway has provided access to just below the summit, opening the peak to broader tourism. Despite this technical development, the mountain's northern side retains a wild character and remains a popular destination for freeride skiers and ski tourers. Geologically, the area consists of crystalline rocks of the Silvretta nappe. The flora during the summer months is remarkably diverse, as the mountain is located in a climatic transition zone. The summit offers an expansive view over the Paznaun Valley and the glaciated peaks of the Silvretta Range.",
      es: "El Piz Val Gronda es una montaña de 2812 m de altura en los Alpes de Bernina, al sur del glaciar Morteratsch. Se compone de roca sedimentaria de la formación de dolomita. La montaña es poco visitada porque queda eclipsada por el más conocido Piz Morteratsch. Su flanco norte es empinado y rocoso, mientras que el lado sur se caracteriza por prados alpinos. El nombre deriva del retorrománico 'val gronda', que significa 'gran valle'. La región es hábitat de marmotas y águilas reales. La cumbre ofrece una buena vista del valle de Roseg.",
      pt: "O Piz Val Gronda é uma montanha de 2812 m de altura nos Alpes Bernina, a sul do glaciar Morteratsch. É composto por rocha sedimentar da formação de dolomita. A montanha é pouco visitada porque é eclipsada pelo mais conhecido Piz Morteratsch. O seu flanco norte é íngreme e rochoso, enquanto o lado sul é caracterizado por prados alpinos. O nome deriva do romanche 'val gronda', que significa 'grande vale'. A região é habitat de marmotas e águias reais. O cume oferece uma boa vista do vale de Roseg.",
      fr: "Le Piz Val Gronda est une montagne de 2812 m d'altitude dans les Alpes de la Bernina, au sud du glacier du Morteratsch. Elle est composée de roche sédimentaire de la formation dolomitique. La montagne est peu visitée car elle est éclipsée par le Piz Morteratsch, plus connu. Son flanc nord est raide et rocheux, tandis que le côté sud est caractérisé par des prairies alpines. Le nom dérive du romanche 'val gronda', qui signifie 'grand vallon'. La région est l'habitat des marmottes et des aigles royaux. Le sommet offre une belle vue sur la vallée de Roseg.",
    },
    factsAdvanced: {
      de: ["Die Gipfelhöhe des Piz Val Gronda beträgt 2812 Meter.", "Der Berg bildet die Staatsgrenze zwischen der Schweiz und Österreich.", "Die Piz Val Gronda E5 Seilbahn wurde im Dezember 2013 eröffnet.", "Der Gipfel ist ein bekannter Aussichtspunkt für die Silvretta-Berge.", "Geografisch liegt der Berg südlich von Ischgl.", "Die Region ist bekannt für ihre hohen Niederschlagsmengen im Winter."],
      hu: ["A Piz Val Gronda csúcsmagassága 2812 méter.", "A hegy államhatárt képez Svájc és Ausztria között.", "A Piz Val Gronda E5 felvonót 2013 decemberében adták át.", "A csúcs népszerű kilátópont a Silvretta-hegység felé.", "Földrajzilag Ischgl településétől délre helyezkedik el.", "A hegyoldalak kiváló terepet biztosítanak a mélyhavas síeléshez."],
      ro: ["Altitudinea vârfului Piz Val Gronda este de 2812 metri.", "Muntele formează granița de stat între Elveția și Austria.", "Telecabina Piz Val Gronda E5 a fost deschisă în decembrie 2013.", "Vârful este un punct de observație renumit pentru munții Silvretta.", "Geografic, muntele este situat la sud de localitatea Ischgl.", "Regiunea este cunoscută pentru cantitățile mari de precipitații iarna."],
      en: ["The summit of Piz Val Gronda stands at 2,812 meters.", "The mountain marks the international border between Switzerland and Austria.", "The Piz Val Gronda E5 cable car was inaugurated in December 2013.", "It serves as a key access point for off-piste skiing in the Ischgl area.", "The peak is part of the extensive Silvretta Arena ski infrastructure.", "In summer, it is a popular destination for mountain bikers and hikers."],
      es: ["Altura: 2812 m", "Tipo de roca: Dolomita, piedra caliza", "Ubicación: al sur del glaciar Morteratsch", "Fauna: marmotas, águilas reales", "Especies de plantas: más de 200 especies alpinas", "Nombre: retorrománico 'gran valle'"],
      pt: ["Altura: 2812 m", "Tipo de rocha: Dolomita, calcário", "Localização: a sul do glaciar Morteratsch", "Fauna: marmotas, águias reais", "Espécies de plantas: mais de 200 espécies alpinas", "Nome: romanche 'grande vale'"],
      fr: ["Altitude : 2812 m", "Type de roche : Dolomie, calcaire", "Localisation : au sud du glacier du Morteratsch", "Faune : marmottes, aigles royaux", "Espèces végétales : plus de 200 espèces alpines", "Nom : romanche 'grand vallon'"],
    },
