    imageHint: "Piz della Drausa Ticino",
    descriptionAdvanced: {
      de: "Der Piz della Drausa, oft auch Piz d'la Drosa genannt, ist ein 3172 Meter hoher Berggipfel in den Livigno-Alpen im Kanton Graubünden. Er befindet sich an der östlichen Grenze des Schweizer Nationalparks, unweit des Ofenpasses und des Munt la Schera. Geologisch ist der Berg durch die Gesteine der Engadiner Dolomiten geprägt, was zu einer markanten, oft rötlichen und spröden Felsstruktur führt. Der Gipfel markiert einen wichtigen Punkt in der Gebirgskette zwischen dem Val dal Spöl und dem Val Müstair. Trotz seiner beachtlichen Höhe ist der Piz della Drausa weniger stark frequentiert als andere Gipfel der Region, was ihn zu einem Ziel für Alpinisten macht, die Einsamkeit suchen. Der Aufstieg bietet spektakuläre Einblicke in die unberührte Natur des Nationalparks und die wilden Täler an der Grenze zu Italien. Von oben reicht der Blick über die weiten Landschaften von Livigno bis hin zu den vergletscherten Riesen der Ortler-Gruppe im Osten.",
      hu: "A Piz della Drausa (gyakran Piz d'la Drosa) egy 3172 méter magas hegycsúcs a Livigno-Alpokban, Graubünden kantonban. A Svájci Nemzeti Park keleti határán található, közel az Ofen-hágóhoz és a Munt la Schera tömbjéhez. Geológiailag az Engadini-Dolomitok kőzetei határozzák meg, ami jellegzetes, gyakran vöröses árnyalatú és omlós sziklaszerkezetet eredményez. A csúcs fontos pontot jelöl a Val dal Spöl és a Val Müstair közötti hegyvonulatban. Tekintélyes magassága ellenére a Piz della Drausa kevésbé látogatott, mint a régió más csúcsai, így ideális célpont a magányt kedvelő hegymászók számára. A feljutás során lenyűgöző betekintést nyerhetünk a nemzeti park érintetlen természetébe és az olasz határ menti vad völgyekbe. A csúcsról a kilátás Livigno tágas tájaitól egészen a keletre fekvő Ortler-csoport gleccseres óriásaiig terjed.",
      ro: "Piz della Drausa, numit adesea și Piz d'la Drosa, este un vârf montan de 3172 de metri situat în Alpii Livigno din cantonul Grisunilor. Acesta se află la granița estică a Parcului Național Elvețian, în apropiere de Pasul Ofen și de muntele Munt la Schera. Din punct de vedere geologic, muntele este caracterizat de rocile Dolomitului de Engadina, fapt ce duce la o structură stâncoasă distinctă, adesea roșiatică și fărâmicioasă. Vârful marchează un punct important în lanțul muntos dintre Val dal Spöl și Val Müstair. În ciuda înălțimii sale considerabile, Piz della Drausa este mai puțin frecventat decât alte vârfuri din regiune, devenind o destinație pentru alpiniștii care caută solitudinea. Ascensiunea oferă perspective spectaculoase asupra naturii neatinse a parcului național și a văilor sălbatice de la granița cu Italia. De la înălțime, priveliștea se întinde de la peisajele din Livigno până la giganții înghețați ai grupului Ortler la est.",
      en: "Piz della Drausa, often referred to as Piz d'la Drosa, is a 3172-meter high mountain peak in the Livigno Alps, located in the canton of Graubünden. It stands on the eastern boundary of the Swiss National Park, not far from the Ofen Pass and Munt la Schera. Geologically, the mountain is defined by the rocks of the Engadine Dolomites, resulting in a distinct, often reddish and brittle rock structure. The summit marks an important point in the mountain chain between Val dal Spöl and Val Müstair. Despite its considerable height, Piz della Drausa is less frequented than other peaks in the region, making it a prime destination for mountaineers seeking solitude. The ascent offers spectacular insights into the untouched nature of the national park and the wild valleys on the border with Italy. From the top, the view stretches across the vast landscapes of Livigno to the glaciated giants of the Ortler Group to the east.",
      es: "El Piz della Drausa es una montaña de 3250 m en los Alpes de Livigno, Grisones. Se encuentra cerca de la frontera italiana. El nombre 'Drausa' proviene del romanche y significa 'zorzal' (ave). La montaña está poco desarrollada y ofrece caminatas solitarias. El entorno es rico en animales salvajes como ciervos y águilas. La cima ofrece una amplia vista del Val Müstair.",
      pt: "O Piz della Drausa é uma montanha de 3250 m nos Alpes de Livigno, Grisões. Situa-se perto da fronteira italiana. O nome 'Drausa' provém do romanche e significa 'tordo' (pássaro). A montanha é pouco desenvolvida e oferece caminhadas solitárias. O ambiente é rico em animais selvagens como veados e águias. O cume oferece uma vista ampla do Val Müstair.",
      fr: "Le Piz della Drausa est une montagne de 3250 m dans les Alpes de Livigno, aux Grisons. Il se situe près de la frontière italienne. Le nom 'Drausa' provient du romanche et signifie 'grive' (oiseau). La montagne est peu aménagée et offre des randonnées solitaires. L'environnement est riche en animaux sauvages tels que les cerfs et les aigles. Le sommet offre une vue étendue sur le Val Müstair.",
    },
    factsAdvanced: {
      de: ["Höhe: 3172 Meter über Meer.", "Gebirge: Livigno-Alpen (Sektion der Rätischen Alpen).", "Lage: Kanton Graubünden, Rand des Schweizer Nationalparks.", "Geologie: Besteht aus Engadiner Dolomitgestein.", "Dominanz: 3,4 Kilometer zum Piz da l'Acqua.", "Grenzlage: Liegt nahe der Wasserscheide zwischen Donau und Po."],
      hu: ["Magasság: 3172 méter a tengerszint felett.", "Hegység: Livigno-Alpok (Rhaeti-Alpok része).", "Helyszín: Graubünden kanton, a Svájci Nemzeti Park szélén.", "Kőzet: Főként engadini dolomit építi fel.", "Relatív magasság: 180 méter a környező nyergekhez képest.", "Vízválasztó: A Duna és a Pó folyók vízgyűjtőjének közelében fekszik."],
      ro: ["Altitudine: 3172 metri deasupra nivelului mării.", "Grup montan: Alpii Livigno (Alpii Retici).", "Localizare: Cantonul Grisunilor, la marginea Parcului Național.", "Geologie: Compus din roci de tip Dolomit de Engadina.", "Dominanță: 3,4 km până la vârful Piz da l'Acqua.", "Hidrografie: Situat aproape de cumpăna apelor între Dunăre și Po."],
      en: ["Elevation: 3172 meters (10,407 feet).", "Range: Livigno Alps (Central Eastern Alps).", "Location: Canton of Graubünden, near the Swiss National Park.", "Geology: Part of the Engadine Dolomites formation.", "Prominence: 180 meters above the nearest col.", "Accessibility: Approached via remote trails from the Ofen Pass area."],
      es: ["Altura: 3250 m", "Nombre: 'zorzal' en romanche", "Ubicación: cerca de la frontera italiana", "Fauna: ciervos, águilas", "Valle: Val Müstair con monasterio de la UNESCO", "Tipo de roca: Dolomita"],
      pt: ["Altitude: 3250 m", "Nome: 'tordo' em romanche", "Localização: perto da fronteira italiana", "Fauna: veados, águias", "Valle: Val Müstair com mosteiro da UNESCO", "Tipo de rocha: Dolomite"],
      fr: ["Altitude : 3250 m", "Nom : 'grive' en romanche", "Localisation : près de la frontière italienne", "Faune : cerfs, aigles", "Vallée : Val Müstair avec monastère de l'UNESCO", "Type de roche : Dolomite"],
    },
