    imageHint: "Piz Terri mountain summit",
    descriptionAdvanced: {
      de: "Der Piz Terri ist ein markanter Gipfel in den Adula-Alpen, der eine Höhe von 3149 Metern über dem Meeresspiegel erreicht. Er liegt an der strategischen Grenze zwischen den Schweizer Kantonen Graubünden und Tessin und überragt die unberührte Greina-Hochebene. Geologisch zeichnet sich der Berg durch seine dunklen Schieferformationen aus, die ihm eine fast schwarze, pyramidenförmige Silhouette verleihen. Die Erstbesteigung erfolgte bereits im Jahr 1801 durch den Benediktinerpater Placidus a Spescha, einen Pionier der alpinen Forschung. Der Berg ist ein beliebtes Ziel für erfahrene Alpinisten, wobei die Terrihütte auf 2170 Metern als zentraler Ausgangspunkt dient. Von seinem Gipfel aus bietet sich ein weiter Blick auf den Stausee Lago di Luzzone und die umliegenden Gletschergebiete. Die Region ist heute als geschützte Moorlandschaft von nationaler Bedeutung eingestuft und bewahrt eine einzigartige hochalpine Flora und Fauna.",
      hu: "A Piz Terri az Adula-Alpok egyik leglátványosabb hegycsúcsa, amely 3149 méteres magasságba emelkedik Graubünden és Ticino kantonok határán. A hegy uralja a Greina-fennsík kietlen, mégis fenséges táját, amely Svájc egyik legfontosabb érintetlen alpesi területe. Kőzettani szempontból sötét pala és gneisz építi fel, ami jellegzetes, piramisra emlékeztető formát és sötét tónust kölcsönöz a csúcsnak. Első dokumentált megmászása 1801-ben történt Placidus a Spescha bencés szerzetes által, aki a régió feltérképezésének úttörője volt. A hegymászók számára a 2170 méteren fekvő Terri-menedékház biztosít pihenőhelyet a csúcstámadás előtt. A csúcsról lenyűgöző panoráma nyílik a Lago di Luzzone víztározóra és a környező háromezres csúcsokra. A terület ökológiai jelentősége kiemelkedő, mivel a Greina-fennsík része egy országos védettséget élvező vizes élőhely-rendszernek.",
      ro: "Piz Terri este un vârf proeminent din Alpii Adula, situat la o altitudine de 3149 de metri deasupra nivelului mării. Acesta se află la granița dintre cantoanele elvețiene Graubünden și Ticino, dominând platoul înalt Greina, o zonă de o frumusețe sălbatică rară. Din punct de vedere geologic, muntele este compus în principal din șisturi întunecate, ceea ce îi conferă o siluetă piramidală distinctă și o culoare aproape neagră. Prima ascensiune documentată a fost realizată în anul 1801 de către călugărul benedictin Placidus a Spescha, un pionier al alpinismului în această regiune. Cabana Terri, situată la 2170 de metri, servește drept punct principal de plecare pentru drumeții care doresc să cucerească vârful. De sus, vizitatorii pot admira o panoramă vastă asupra lacului de acumulare Lago di Luzzone și a masivelor montane învecinate. Regiunea este protejată la nivel național datorită biotopurilor sale unice de mlaștină și peisajului alpin conservat.",
      en: "Piz Terri is a prominent mountain peak in the Adula Alps, reaching an elevation of 3,149 meters above sea level. It stands on the border between the Swiss cantons of Graubünden and Ticino, overlooking the pristine Greina Plateau. Geologically, the mountain is characterized by its dark shale formations, which give it a distinct pyramidal shape and a dark, imposing appearance. The first recorded ascent took place in 1801 by the Benedictine monk Placidus a Spescha, a pioneer of alpine exploration in the region. Mountaineers typically use the Terri Hut, located at 2,170 meters, as a base for their summit attempts. From the top, the peak offers expansive views of the Lago di Luzzone reservoir and the surrounding high-altitude terrain. Today, the area is recognized as a protected moorland of national importance, preserving a unique ecosystem within the Central Alps.",
      es: "El Piz Terri es una montaña de 3149 m de altura en los Alpes Adula, Grisones. Es la cumbre más alta de la meseta Greina. El nombre 'Terri' deriva del retorrománico 'terr' (tierra). La montaña es conocida por su región de cumbre plana y cubierta de hierba. La región es una importante zona de divisoria de aguas entre el Rin y el Po. El Paso Greina es un cruce histórico. La zona es un páramo alto de importancia nacional.",
      pt: "O Piz Terri é uma montanha de 3149 m de altura nos Alpes Adula, Grisões. É o cume mais alto do planalto Greina. O nome 'Terri' deriva do romanche 'terr' (terra). A montanha é conhecida pela sua região de cume plana e coberta de erva. A região é uma importante zona de divisória de águas entre o Reno e o Pó. O Passo Greina é uma passagem histórica. A área é um charco de montanha de importância nacional.",
      fr: "Le Piz Terri est une montagne de 3149 m d'altitude dans les Alpes de l'Adula, dans les Grisons. C'est le plus haut sommet du plateau de la Greina. Le nom 'Terri' dérive du romanche 'terr' (terre). La montagne est connue pour sa région sommitale plate et herbeuse. La région est une zone importante de ligne de partage des eaux entre le Rhin et le Pô. Le col de la Greina est un passage historique. La zone est un haut-marais d'importance nationale.",
    },
    factsAdvanced: {
      de: ["Die offizielle Gipfelhöhe beträgt 3149 Meter über dem Meeresspiegel.", "Der Berg liegt an der kontinentalen Wasserscheide zwischen Po und Rhein.", "Pater Placidus a Spescha erreichte den Gipfel erstmals im Jahr 1801.", "Das Gestein besteht überwiegend aus Bündnerschiefer der penninischen Decke.", "Die Terrihütte des SAC bietet Platz für etwa 110 Übernachtungsgäste.", "Der Piz Terri liegt innerhalb des Bundesinventars der Landschaften von nationaler Bedeutung."],
      hu: ["A hegycsúcs pontos magassága 3149 méter a tengerszint felett.", "A csúcs a Pó és a Rajna folyók közötti kontinentális vízválasztón található.", "Placidus a Spescha 1801-ben hajtotta végre az első sikeres csúcstámadást.", "A hegyet alkotó kőzet főként sötét tónusú graubündeni pala.", "A 2170 méteren fekvő Terri-menedékház 110 férőhellyel rendelkezik.", "A terület a Greina-fennsík részeként nemzeti tájvédelmi körzetnek számít."],
      ro: ["Înălțimea oficială a vârfului este de 3149 de metri peste nivelul mării.", "Muntele este situat pe cumpăna apelor dintre bazinele hidrografice ale Rinului și Padului.", "Prima ascensiune a fost realizată de Placidus a Spescha în anul 1801.", "Compoziția geologică principală este reprezentată de șisturile de tip Bündner.", "Cabana Terri, aflată la 2170 m altitudine, dispune de 110 locuri de cazare.", "Piz Terri face parte dintr-o zonă protejată inclusă în inventarul federal elvețian."],
      en: ["The official summit height is 3,149 meters above sea level.", "It sits on the continental divide between the Rhine and Po river basins.", "The first recorded ascent was completed in 1801 by Placidus a Spescha.", "The mountain is primarily composed of dark Bündner shale rock.", "The Terri Hut (Terrihütte) provides accommodation for up to 110 people.", "Piz Terri is part of the Greina region, a landscape of national significance in Switzerland."],
      es: ["Altura: 3149 m", "Nombre: retorrománico 'tierra'", "Región: Meseta Greina", "Divisoria de aguas: Rin/Po", "Estatus de protección: Páramo alto de importancia nacional", "Paso: Paso Greina, histórico"],
      pt: ["Altura: 3149 m", "Nome: romanche 'terra'", "Região: Planalto Greina", "Divisória de águas: Reno/Pó", "Estatuto de proteção: Charco de montanha de importância nacional", "Passo: Passo Greina, histórico"],
      fr: ["Altitude : 3149 m", "Nom : romanche 'terre'", "Région : Plateau de la Greina", "Ligne de partage des eaux : Rhin/Pô", "Statut de protection : Haut-marais d'importance nationale", "Col : Col de la Greina, historique"],
    },
