      en: "The Piz dal Luch is located in the canton of Graubünden. It belongs to the peaks in the surroundings of the Bernina Range.",
      es: "El Piz dal Luch se encuentra en el cantón de los Grisones. Pertenece a las cimas en los alrededores del grupo Bernina.",
      pt: "O Piz dal Luch situa-se no cantão dos Grisões. Pertence aos cumes nos arredores do grupo Bernina.",
