    imageHint: "Piz della Drausa secondary peak",
    descriptionAdvanced: {
      de: "Der Piz della Drosa II (oder Piz della Drausa) ist ein Gipfel in den Livigno-Alpen mit einer Höhe von 3173 Metern. Er liegt direkt auf der Grenze zwischen der Schweiz (Graubünden) und Italien (Lombardei), unweit des Berninapasses. Der Berg ist durch eine karge, hochalpine Felslandschaft gekennzeichnet, die fast das ganze Jahr über Schneefelder aufweisen kann. Geologisch gehört das Massiv zu den Ostalpin-Einheiten und besteht primär aus metamorphen Gesteinen. Der Piz della Drosa bietet einen weitreichenden Ausblick auf das Valle di Livigno im Osten und die Gletscherwelt der Bernina im Westen. Der Zustieg erfolgt meist von der Fuorcla da la Stretta oder direkt von der Passstraße des Berninapasses. Aufgrund seiner Grenzlage war der Berg historisch ein Beobachtungspunkt für Zollwachen. Heute schätzen Bergsteiger den Gipfel für seine Ruhe abseits der großen Touristenströme.",
      hu: "A Piz della Drosa II (vagy Piz della Drausa) egy 3173 méter magas csúcs a Livigno-Alpokban. Közvetlenül Svájc (Graubünden) és Olaszország (Lombardia) határán fekszik, nem messze a Bernina-hágótól. A hegyet kietlen, magashegyi sziklás táj jellemzi, ahol az év nagy részében hófoltok láthatók. Földtanilag a masszívum az Ostalpin egységekhez tartozik, és elsősorban metamorf kőzetekből épül fel. A Piz della Drosa messzire nyúló kilátást nyújt keletre a Valle di Livigno völgyre, nyugatra pedig a Bernina gleccservilágára. A megközelítés általában a Fuorcla da la Stretta hágótól vagy közvetlenül a Bernina-hágó útjáról történik. Határmenti elhelyezkedése miatt a hegy történelmileg a vámszervek megfigyelőpontjaként is szolgált. Ma a hegymászók a csúcsot a nagy turistaáradattól távoli nyugalma miatt kedvelik.",
      ro: "Piz della Drosa II (sau Piz della Drausa) este un vârf din Alpii Livigno cu o înălțime de 3173 de metri. Acesta este situat direct pe granița dintre Elveția (Graubünden) și Italia (Lombardia), nu departe de pasul Bernina. Muntele este caracterizat printr-un peisaj stâncos alpin arid, care poate prezenta petice de zăpadă aproape tot anul. Din punct de vedere geologic, masivul aparține unităților alpine orientale și constă în principal din roci metamorfice. Piz della Drosa oferă o vedere extinsă asupra Valle di Livigno la est și asupra lumii glaciare a masivului Bernina la vest. Accesul se face de obicei de la Fuorcla da la Stretta sau direct de pe drumul pasului Bernina. Datorită locației sale de frontieră, muntele a fost istoric un punct de observație pentru gărzile vamale. Astăzi, alpinistii apreciază vârful pentru liniștea sa, departe de marile fluxuri turistice.",
      en: "Piz della Drosa II (also referred to as Piz della Drausa) is a peak in the Livigno Alps, reaching an elevation of 3,173 meters. It stands directly on the border between Switzerland (Graubünden) and Italy (Lombardy), close to the Bernina Pass. The mountain is characterized by a barren, high-alpine rocky landscape that often retains snow fields throughout most of the year. Geologically, the massif belongs to the Austroalpine nappes and consists primarily of metamorphic rocks. Piz della Drosa offers expansive views of the Valle di Livigno to the east and the glaciated terrain of the Bernina Range to the west. Access is typically gained via the Fuorcla da la Stretta or directly from the Bernina Pass road. Due to its border position, the mountain historically served as an observation point for customs guards. Today, mountaineers value the summit for its tranquility, away from the main tourist routes.",
      es: "El Piz della Drausa II es una cima secundaria de 3220 m del Piz della Drausa. Se encuentra al noreste de la cima principal. La montaña es menos visitada y ofrece soledad. El ascenso requiere sentido de la orientación. La cima ofrece una vista similar a la de la cima principal, hacia el Val Müstair y los Alpes italianos. El entorno es rocoso y está intercalado con prados alpinos.",
      pt: "O Piz della Drausa II é um cume secundário de 3220 m do Piz della Drausa. Situa-se a nordeste do cume principal. A montanha é menos visitada e oferece solidão. A subida requer sentido de orientação. O cume oferece uma vista semelhante à do cume principal, para o Val Müstair e os Alpes italianos. O ambiente é rochoso e intercalado com prados alpinos.",
      fr: "Le Piz della Drausa II est un sommet secondaire de 3220 m du Piz della Drausa. Il se situe au nord-est du sommet principal. La montagne est moins visitée et offre de la solitude. L'ascension nécessite un sens de l'orientation. Le sommet offre une vue similaire à celle du sommet principal, sur le Val Müstair et les Alpes italiennes. L'environnement est rocheux et entrecoupé de prairies alpines.",
    },
    factsAdvanced: {
      de: ["Die Gipfelhöhe beträgt 3173 Meter über dem Meeresspiegel.", "Der Berg liegt an der Staatsgrenze zwischen der Schweiz und Italien.", "Er gehört zur Untergruppe der Livigno-Alpen.", "Geologisch ist der Gipfel Teil des ostalpinen Kristallins.", "Schnee- und Eisfelder finden sich oft bis in den Spätsommer.", "Der nächste größere Talort auf Schweizer Seite ist Pontresina."],
      hu: ["A csúcs magassága 3173 méter a tengerszint felett.", "A hegy Svájc és Olaszország államhatárán helyezkedik el.", "A Livigno-Alpok egyik jelentős háromezres csúcsa.", "Földtanilag az ostalpini kristályos kőzetek része.", "Hó- és jégfoltok gyakran még késő nyáron is megtalálhatók rajta.", "A legközelebbi nagyobb svájci település Pontresina."],
      ro: ["Înălțimea vârfului este de 3173 de metri deasupra nivelului mării.", "Muntele se află pe granița de stat dintre Elveția și Italia.", "Aparține subgrupului Alpilor Livigno.", "Geologic, vârful face parte din cristalinul alpin oriental.", "Câmpuri de zăpadă și gheață se găsesc adesea până la sfârșitul verii.", "Cea mai apropiată localitate importantă de pe partea elvețiană este Pontresina."],
      en: ["The summit height is 3,173 meters above sea level.", "The mountain is located on the national border between Switzerland and Italy.", "It belongs to the Livigno Alps subgroup of the Alps.", "Geologically, the peak is part of the Austroalpine crystalline basement.", "Snow and ice patches can often be found until late summer.", "The nearest major town on the Swiss side is Pontresina."],
      es: ["Altura: 3220 m", "Ubicación: noreste de la cima principal", "Visitantes: raros", "Orientación: necesaria", "Vista: Val Müstair, Alpes italianos", "Terreno: rocoso, prados alpinos"],
      pt: ["Altitude: 3220 m", "Localização: nordeste do cume principal", "Visitantes: raros", "Orientação: necessária", "Vista: Val Müstair, Alpes italianos", "Terreno: rochoso, prados alpinos"],
      fr: ["Altitude : 3220 m", "Localisation : nord-est du sommet principal", "Visiteurs : rares", "Orientation : nécessaire", "Vue : Val Müstair, Alpes italiennes", "Terrain : rocheux, prairies alpines"],
    },
