      de: ["Höhe: 3150 m", "Lage: Graubünden/Tessin", "Adula-Alpen", "Hochtour"],
      hu: ["Magasság: 3150 m", "Helyszín: Graubünden/Tessin", "Adula-Alpok", "Magashegyi túra"],
