      es: ["Altitud: 3150 m", "Ubicación: Grisones/Tesino", "Alpes Adula", "Excursión de alta montaña"],
      pt: ["Altitude: 3150 m", "Localização: Grisões/Ticino", "Alpes Adula", "Excursão de alta montanha"],
