    imageHint: "Piz d'Artgas South peak",
    descriptionAdvanced: {
      de: "Der Piz d'Artgas South ist ein Berggipfel in der Region des Lukmanierpasses in den Adula-Alpen mit einer Höhe von etwa 3037 Metern. Er liegt südlich des Hauptgipfels Piz d'Artgas und gehört zum Kanton Graubünden. Die Landschaft ist durch schroffe Felsformationen und steile Geröllhalden charakterisiert, die typisch für die zentralen rätischen Alpen sind. Geologisch besteht der Berg aus einer Mischung von kristallinen Gesteinen und Sedimenten der Adula-Decke. Der Gipfel bietet einen hervorragenden Blick auf den Lai da Sontga Maria und das Val Medel. Der Zugang zum Berg ist anspruchsvoll und führt oft durch wegloses Gelände, was ihn zu einem Ziel für erfahrene Alpinisten macht. Historisch wurde das Gebiet durch die Nähe zum Lukmanierpass, einem wichtigen Nord-Süd-Übergang, schon früh kartiert. Heute ist der Piz d'Artgas South ein Ort der Stille, der selten besucht wird und seinen wilden Charakter bewahrt hat.",
      hu: "A Piz d'Artgas South egy hegycsúcs a Lukmanier-hágó régiójában, az Adula-Alpokban, körülbelül 3037 méteres magasságban. A főcsúcstól, a Piz d'Artgastól délre található, Graubünden kanton területén. A tájat meredek sziklaalakzatok és törmeléklejtők jellemzik, amelyek a központi Réti-Alpokra jellemzőek. Földtanilag a hegy az Adula-takaró kristályos kőzeteinek és üledékeinek keverékéből áll. A csúcsról kiváló kilátás nyílik a Lai da Sontga Maria víztározóra és a Val Medel völgyre. A hegy megközelítése kihívást jelent, és gyakran jelöletlen terepen vezet keresztül, ami a tapasztalt alpinisták célpontjává teszi. Történelmileg a területet a Lukmanier-hágó közelsége miatt – amely fontos észak-déli átjáró – korán feltérképezték. Ma a Piz d'Artgas South a nyugalom helyszíne, amelyet ritkán látogatnak, így megőrizte vad jellegét.",
      ro: "Piz d'Artgas South este un vârf montan în regiunea pasului Lukmanier, în Alpii Adula, având o înălțime de aproximativ 3037 de metri. Acesta se află la sud de vârful principal Piz d'Artgas și aparține cantonului Graubünden. Peisajul este caracterizat prin formațiuni stâncoase abrupte și grohotișuri, tipice pentru Alpii Retici centrali. Din punct de vedere geologic, muntele constă dintr-un amestec de roci cristaline și sedimente ale unității Adula. Vârful oferă o vedere excelentă asupra lacului Lai da Sontga Maria și a văii Val Medel. Accesul la munte este solicitant și trece adesea prin teren fără poteci, ceea ce îl face o destinație pentru alpiniștii experimentați. Din punct de vedere istoric, zona a fost cartografiată devreme datorită proximității față de pasul Lukmanier, o trecătoare importantă nord-sud. Astăzi, Piz d'Artgas South este un loc al liniștii, vizitat rar, care și-a păstrat caracterul sălbatic.",
      en: "Piz d'Artgas South is a mountain peak in the Lukmanier Pass region of the Adula Alps, standing at approximately 3,037 meters. Located south of the main Piz d'Artgas summit, it lies within the canton of Graubünden. The terrain is characterized by rugged rock formations and steep scree slopes, typical of the central Rhaetian Alps. Geologically, the mountain is composed of a mix of crystalline rocks and sediments from the Adula nappe. The summit offers outstanding views over the Lai da Sontga Maria reservoir and Val Medel. Reaching the peak is challenging and often involves navigating pathless terrain, making it a goal for experienced mountaineers. Historically, the area was mapped early due to its proximity to the Lukmanier Pass, a vital north-south crossing point. Today, Piz d'Artgas South remains a place of solitude, rarely visited and preserving its wild character.",
      es: "El Piz d'Artgas Sur (3268 m) es un pico en la región de Surselva, Grisones. La montaña pertenece al grupo Tödi y es conocida por su escarpada cara norte. La roca consiste principalmente en aplita y granito. El lado sur tiene laderas cubiertas de hierba, utilizadas por senderistas en verano. La cima ofrece una amplia vista sobre el valle del Rin Anterior. La región está culturalmente marcada por la lengua retorrománica. La primera ascensión tuvo lugar en 1877. La ruta normal lleva desde la Camona da Biferten a través de una vía ferrata.",
      pt: "O Piz d'Artgas Sul (3268 m) é um cume na região de Surselva, Grisões. A montanha pertence ao grupo Tödi e é conhecida pela sua escarpa face norte. A rocha é composta principalmente por aplito e granito. O lado sul apresenta encostas cobertas de relva, utilizadas pelos caminhantes no verão. O cume oferece uma vista ampla sobre o vale do Reno Anterior. A região é culturalmente marcada pela língua romanche. A primeira ascensão ocorreu em 1877. A rota normal conduz da Camona da Biferten através de uma via ferrata.",
      fr: "Le Piz d'Artgas Sud (3268 m) est un sommet dans la région de la Surselva, aux Grisons. La montagne appartient au groupe du Tödi et est connue pour sa face nord abrupte. La roche se compose principalement d'aplite et de granit. Le versant sud présente des pentes herbeuses, utilisées par les randonneurs en été. Le sommet offre une vue étendue sur la vallée du Rhin antérieur. La région est culturellement marquée par la langue romanche. La première ascension a eu lieu en 1877. La voie normale mène depuis la Camona da Biferten via une via ferrata.",
    },
    factsAdvanced: {
      de: ["Die Höhe des Piz d'Artgas South liegt bei ca. 3037 Metern.", "Er befindet sich in der Nähe des Lukmanierpasses.", "Geologisch gehört der Berg zur Adula-Decke.", "Der Gipfel bietet Panoramablicke auf das Medelser-Massiv.", "Der Aufstieg ist technisch anspruchsvoll und oft weglos.", "Die Region ist ein wichtiges Wassereinzugsgebiet für den Rhein."],
      hu: ["A Piz d'Artgas South magassága körülbelül 3037 méter.", "A Lukmanier-hágó közelében található.", "Földtanilag a hegy az Adula-takaróhoz tartozik.", "A csúcsról panorámás kilátás nyílik a Medel-masszívumra.", "A csúcstámadás technikailag nehéz és gyakran jelöletlen utakon folyik.", "A régió a Rajna folyó egyik fontos vízgyűjtő területe."],
      ro: ["Înălțimea vârfului Piz d'Artgas South este de cca. 3037 de metri.", "Este situat în apropierea pasului Lukmanier.", "Geologic, muntele aparține unității tectonice Adula.", "Vârful oferă vederi panoramice asupra masivului Medel.", "Ascensiunea este tehnică și adesea fără trasee marcate.", "Regiunea este un bazin de colectare a apei important pentru râul Rin."],
      en: ["The elevation of Piz d'Artgas South is approximately 3,037 meters.", "It is located near the Lukmanier Pass.", "Geologically, the mountain is part of the Adula nappe.", "The summit provides panoramic views of the Medel massif.", "The ascent is technically demanding and often pathless.", "The region serves as an important catchment area for the Rhine river."],
      es: ["Altitud: 3268 m s.n.m.", "Primera ascensión: 1877", "Geología: Aplita y granito", "Ubicación: Grupo Tödi, Surselva", "Ruta normal: vía ferrata desde Camona da Biferten (2330 m)", "Dificultad: WS (Escala SAC)"],
      pt: ["Altitude: 3268 m s.n.m.", "Primeira ascensão: 1877", "Geologia: Aplito e granito", "Localização: Grupo Tödi, Surselva", "Rota normal: via ferrata a partir de Camona da Biferten (2330 m)", "Dificuldade: WS (Escala SAC)"],
      fr: ["Altitude : 3268 m s.n.m.", "Première ascension : 1877", "Géologie : Aplite et granit", "Emplacement : Groupe du Tödi, Surselva", "Voie normale : via ferrata depuis la Camona da Biferten (2330 m)", "Difficulté : WS (échelle SAC)"],
    },
