      en: ["Elevation: 3120 m", "Location: Graubünden/Ticino", "Adula Alps", "Hiking"],
      es: ["Altura: 3120 m", "Ubicación: Grisones/Tesino", "Alpes Adula", "Senderismo"],
      pt: ["Altura: 3120 m", "Localização: Grisões/Ticino", "Alpes Adula", "Caminhadas"],
